#!/usr/bin/env python3
"""
Validation script for pipeline outputs.
Validates key outputs: selected indicators, cleaned GTFS stops, cleaned POIs,
accessibility scores, and city clusters.
"""

import json
import csv
import os

# Paths
OUTPUTS_DIR = "outputs"
SUMMARY_FILE = os.path.join(OUTPUTS_DIR, "t14_validation_summary.json")

# Define validation checks
CHECKS = [
    {
        "check_name": "selected_indicators_exists",
        "description": "Validate that selected indicators CSV exists and has data",
        "file": os.path.join(OUTPUTS_DIR, "t01_selected_indicators.csv")
    },
    {
        "check_name": "clean_gtfs_stops_exists",
        "description": "Validate that cleaned GTFS stops CSV exists and has data",
        "file": os.path.join(OUTPUTS_DIR, "t05_clean_stops.csv")
    },
    {
        "check_name": "clean_pois_exists",
        "description": "Validate that cleaned POIs CSV exists and has data",
        "file": os.path.join(OUTPUTS_DIR, "t08_pois_clean.csv")
    },
    {
        "check_name": "accessibility_scores_exists",
        "description": "Validate that accessibility scores CSV exists and has data",
        "file": os.path.join(OUTPUTS_DIR, "t10_accessibility_scores.csv")
    },
    {
        "check_name": "city_clusters_exists",
        "description": "Validate that city clusters CSV exists and has data",
        "file": os.path.join(OUTPUTS_DIR, "t13_city_clusters.csv")
    },
    {
        "check_name": "selected_indicators_has_columns",
        "description": "Validate that selected indicators has required columns",
        "file": os.path.join(OUTPUTS_DIR, "t01_selected_indicators.csv"),
        "required_columns": ["indicator_id", "indicator_name", "theme"]
    },
    {
        "check_name": "clean_gtfs_stops_has_coordinates",
        "description": "Validate that cleaned GTFS stops has latitude and longitude",
        "file": os.path.join(OUTPUTS_DIR, "t05_clean_stops.csv"),
        "required_columns": ["stop_id", "stop_name", "stop_lat", "stop_lon"]
    },
    {
        "check_name": "clean_pois_has_location",
        "description": "Validate that cleaned POIs has latitude and longitude",
        "file": os.path.join(OUTPUTS_DIR, "t08_pois_clean.csv"),
        "required_columns": ["qid", "label", "latitude", "longitude"]
    },
    {
        "check_name": "accessibility_scores_has_metrics",
        "description": "Validate that accessibility scores has required metrics",
        "file": os.path.join(OUTPUTS_DIR, "t10_accessibility_scores.csv"),
        "required_columns": ["qid", "accessibility_score", "distance_m"]
    },
    {
        "check_name": "city_clusters_has_year",
        "description": "Validate that city clusters has year column",
        "file": os.path.join(OUTPUTS_DIR, "t13_city_clusters.csv"),
        "required_columns": ["city_id", "city_name", "year", "cluster_id"]
    }
]


def read_csv(filepath):
    """Read CSV file and return list of rows."""
    rows = []
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            for row in reader:
                rows.append(row)
    except Exception as e:
        return None
    return rows


def validate_file_exists(filepath):
    """Check if file exists."""
    return os.path.isfile(filepath)


def validate_file_has_data(filepath):
    """Check if file has data rows."""
    rows = read_csv(filepath)
    return rows is not None and len(rows) > 0


def validate_required_columns(filepath, required_columns):
    """Check if CSV has all required columns."""
    rows = read_csv(filepath)
    if rows is None:
        return False

    if len(rows) == 0:
        return False

    first_row = rows[0]
    first_keys = set(first_row.keys())

    for col in required_columns:
        if col not in first_keys:
            return False

    return True


def validate_column_values(filepath, column_name, validation_fn):
    """Validate all values in a column."""
    rows = read_csv(filepath)
    if rows is None:
        return False

    if len(rows) == 0:
        return False

    for row in rows:
        if column_name not in row:
            return False
        value = row[column_name]
        if not validation_fn(value):
            return False

    return True


def validate_numeric_range(filepath, column_name, min_val, max_val):
    """Validate numeric column is within range."""
    def validate(value):
        try:
            num = float(value)
            return min_val <= num <= max_val
        except (ValueError, TypeError):
            return False

    return validate_column_values(filepath, column_name, validate)


def validate_positive_numeric(filepath, column_name):
    """Validate numeric column is positive."""
    return validate_numeric_range(filepath, column_name, 0, float('inf'))


def run_validation():
    """Run all validations and return results."""
    results = []

    for check in CHECKS:
        check_name = check["check_name"]
        description = check["description"]
        filepath = check["file"]

        passed = True
        message = ""

        if not validate_file_exists(filepath):
            passed = False
            message = f"File not found: {filepath}"
        elif not validate_file_has_data(filepath):
            passed = False
            message = f"File has no data: {filepath}"
        elif "required_columns" in check:
            if not validate_required_columns(filepath, check["required_columns"]):
                passed = False
                missing = [c for c in check["required_columns"] if c not in set(read_csv(filepath)[0].keys())]
                message = f"Missing columns: {missing}"
        elif "column_name" in check and "validation_fn" in check:
            if not validate_column_values(filepath, check["column_name"], check["validation_fn"]):
                passed = False
                message = f"Column validation failed for {check['column_name']}"
        elif "column_name" in check and "min_val" in check:
            if not validate_numeric_range(filepath, check["column_name"], check["min_val"], check["max_val"]):
                passed = False
                message = f"Column {check['column_name']} not within range"
        elif "column_name" in check and "positive" in check:
            if not validate_positive_numeric(filepath, check["column_name"]):
                passed = False
                message = f"Column {check['column_name']} not positive"
        else:
            passed = False
            message = "Unknown check type"

        results.append({
            "check_name": check_name,
            "passed": passed,
            "message": message
        })

    return results


def main():
    """Main entry point."""
    results = run_validation()

    # Ensure outputs directory exists
    os.makedirs(OUTPUTS_DIR, exist_ok=True)

    # Write results
    with open(SUMMARY_FILE, 'w', encoding='utf-8') as f:
        json.dump(results, f, indent=2)

    print(f"Validation complete. Results written to {SUMMARY_FILE}")
    print(f"Passed: {sum(1 for r in results if r['passed'])}/{len(results)}")

    # Return exit code based on results
    all_passed = all(r["passed"] for r in results)
    return 0 if all_passed else 1


if __name__ == "__main__":
    exit(main())

